    public static void quickSort(int[] nums,int start,int end){
      if(start>=end){
        return;
      }
      int pi = partition(nums,start,end);
      quickSort(nums,start,pi-1);
      quickSort(nums,pi+1,end);
    }
    public static int partition(int[] nums,int start,int end){
      int pivot = nums[end];
      int i =start-1;
      int j=start;
      while(j<end){
        if(nums[j]<pivot){
          ++i;
          int temp = nums[i];
          nums[i]=nums[j];
          nums[j]=temp;
        }
        ++j;
      }
      int temp = nums[end];
      nums[end]=nums[i+1];
      nums[i+1]=temp;
